	if len(args) == 0 {
		return errReply("empty command")
	}
	cmd := strings.ToLower(string(args[0]))

	switch cmd {
	case "ping":
		switch len(args) {
		case 1:
			return simpleReply("PONG")
		case 2:
			return bulkReply(args[1])
		default:
			return wrongArityReply(cmd)
		}
	case "echo":
