// result is false when the key is missing or expired.
func (s *store) lookup(key string, nowMs int64) (entry, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	if !ok {
		return entry{}, false
	}
	if expired(e, nowMs) {
		delete(s.m, key)
