	defer s.mu.Unlock()
	s.m[key] = entry{data: cp, expireAt: expireAt}
}

func (s *store) delete(key string, nowMs int64) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	if !ok {
